package web

const page = `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="refresh" content="10"><title>AO Watchtower</title><style>body{font:14px system-ui;margin:2rem;background:#10151c;color:#e8edf2}table{width:100%;border-collapse:collapse}td,th{padding:.6rem;border-bottom:1px solid #39414d;text-align:left}code{font-size:11px}.warn{color:#ffbb55}.demo{padding:.5rem;background:#633}input,button{padding:.35rem;margin:.15rem}.controls{margin:1rem 0;padding:.75rem;background:#18202b}.status{margin-left:.5rem}</style></head><body><h1>AO Watchtower</h1>{{if .Demo}}<p class="demo">DEMO MODE — fake AO boundary; never production automation. Demo admin token: <code>demo-admin-token</code></p>{{end}}<div class="controls"><label>Admin token <input id="token" type="password" autocomplete="off" {{if .Demo}}value="demo-admin-token"{{end}}></label><label>Actor <input id="actor" maxlength="128" value="local-user"></label><button id="kill" data-disabled="{{.AutomationDisabled}}">{{if .AutomationDisabled}}Enable automation{{else}}Disable automation{{end}}</button><span id="status" class="status"></span></div><p>Automation: {{if .AutomationDisabled}}<b class="warn">KILL SWITCH ENABLED</b>{{else}}enabled{{end}} · deliveries {{.Deliveries}} · triggers {{.Triggers}} · diagnoses {{.Diagnoses}} · approvals {{.Approvals}} · sends {{.Sends}}</p><table><tr><th>Time / trigger</th><th>Repository / PR / SHA</th><th>Evaluation</th><th>AO outcome</th><th>Diagnosis</th><th>Approval / send</th><th>Actions</th></tr>{{range .Rows}}<tr><td>{{.CreatedAt}}<br>{{if .TriggerKey}}<code>{{.TriggerKey}}</code>{{end}}</td><td>{{.Repository}} #{{.PullNumber}}<br><code>{{.HeadSHA}}</code></td><td>{{.Evaluation}}</td><td>{{.ProjectID}} {{.SessionID}} {{.SpawnOutcome}}</td><td>{{.Diagnosis}}</td><td>{{.Approval}} {{.SendOutcome}}</td><td>{{if .TriggerKey}}{{if .SendOutcome}}Dispatched{{else}}<button class="approve" data-trigger="{{.TriggerKey}}">Approve</button><button class="fix" data-trigger="{{.TriggerKey}}">Fix with AO</button>{{end}}{{end}}</td></tr>{{end}}</table><script>const status=document.getElementById('status'),token=()=>document.getElementById('token').value,actor=()=>document.getElementById('actor').value;async function post(path,body){let r=await fetch(path,{method:'POST',headers:{Authorization:'Bearer '+token(),'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});status.textContent=r.ok?'Saved':'Request failed';if(r.ok)setTimeout(()=>location.reload(),250)}document.querySelectorAll('.approve').forEach(b=>b.onclick=()=>post('/api/triggers?action=approve&trigger='+encodeURIComponent(b.dataset.trigger),{actor:actor()}));document.querySelectorAll('.fix').forEach(b=>b.onclick=()=>post('/api/triggers?action=fix&trigger='+encodeURIComponent(b.dataset.trigger)));document.getElementById('kill').onclick=function(){post('/api/automation',{disabled:this.dataset.disabled!=='true',actor:actor()})}</script></body></html>`
